        run(cmd_create_group, agent="alpha", group="pair", members=["beta"])
        gm = group_map(base_dir(ns()))
        check("groups: creator + leader auto-included", set(gm["pair"]) == {"alpha", "beta", "leader"})

        # ---- v2: discovery over both briefing forms ----
